import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { getMeetings, getUsers, getPendingHods, approveHod, rejectHod, blacklistUser } from '../../api';

function PrincipalDashboard({ user }) {
  const [meetings, setMeetings] = useState([]);
  const [users, setUsers] = useState([]);
  const [pendingHods, setPendingHods] = useState([]);
  const [msg, setMsg] = useState('');
  const [loading, setLoading] = useState(true);
  const [blacklistModal, setBlacklistModal] = useState(null);
  const [reason, setReason] = useState('');

  useEffect(() => { loadAll(); }, []);

  const loadAll = async () => {
    try {
      const [m, u, p] = await Promise.all([getMeetings(), getUsers(), getPendingHods()]);
      setMeetings(m.data);
      setUsers(u.data);
      setPendingHods(p.data);
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  };

  const flash = (m) => { setMsg(m); setTimeout(() => setMsg(''), 3000); };

  const handleApprove = async (id) => {
    try { await approveHod(id); flash('✅ HOD Approved!'); loadAll(); }
    catch (err) { flash('❌ Failed'); }
  };

  const handleReject = async (id) => {
    if (!window.confirm('Reject this HOD registration?')) return;
    try { await rejectHod(id); flash('HOD registration rejected.'); loadAll(); }
    catch (err) { flash('❌ Failed'); }
  };

  const handleBlacklist = async () => {
    if (!reason.trim()) return alert('Please enter a reason');
    try {
      await blacklistUser(blacklistModal._id, reason);
      flash(`✅ ${blacklistModal.name} blacklisted.`);
      setBlacklistModal(null); setReason('');
      loadAll();
    } catch (err) { flash('❌ Failed'); }
  };

  if (loading) return <div className="loading">Loading...</div>;

  const hods = users.filter(u => u.role === 'hod' && u.isApproved);
  const staff = users.filter(u => u.role === 'staff');
  const blacklisted = users.filter(u => u.isBlacklisted);

  return (
    <div className="bg-wrapper">
      <div className="bg-content">
        <h1 className="page-title text-blue">Principal Dashboard</h1>

        {msg && <div className={`alert ${msg.includes('❌') ? 'alert-error' : 'alert-success'}`}>{msg}</div>}

        {/* Stat Cards */}
        <div className="stat-grid">
          <div className="stat-card">
            <div className="stat-label">Total HODs</div>
            <div className="stat-num">{hods.length}</div>
            <Link to="/principal/manage-hods"><button className="btn btn-outline btn-sm" style={{ marginTop: '0.5rem' }}>Manage</button></Link>
          </div>
          <div className="stat-card">
            <div className="stat-label">Total Staff</div>
            <div className="stat-num blue">{staff.length}</div>
            <Link to="/principal/manage-staff"><button className="btn btn-outline btn-sm" style={{ marginTop: '0.5rem' }}>Manage</button></Link>
          </div>
          <div className="stat-card">
            <div className="stat-label">Total Meetings</div>
            <div className="stat-num blue">{meetings.length}</div>
          </div>
          <div className="stat-card">
            <div className="stat-label" style={{ color: '#dc2626' }}>Blacklisted Users</div>
            <div className="stat-num red">{blacklisted.length}</div>
            <Link to="/principal/blacklist"><button className="btn btn-outline btn-sm" style={{ marginTop: '0.5rem', borderColor: '#dc2626', color: '#dc2626' }}>View List</button></Link>
          </div>
        </div>

        {/* Schedule Button */}
        <div style={{ textAlign: 'center', marginBottom: '1.5rem' }}>
          <Link to="/principal/schedule">
            <button className="btn" style={{ background: '#1e293b', color: 'white', padding: '0.8rem 2rem', fontSize: '1rem' }}>
              📢 Schedule Meeting for All (HOD + Staff)
            </button>
          </Link>
        </div>

        {/* Pending HOD Approvals */}
        {pendingHods.length > 0 && (
          <div className="card" style={{ border: '2px solid #f97316', marginBottom: '1.5rem' }}>
            <h2 style={{ color: '#f97316' }}>⏳ Pending HOD Approvals ({pendingHods.length})</h2>
            <table>
              <thead><tr><th>Name</th><th>Email</th><th>Department</th><th>Actions</th></tr></thead>
              <tbody>
                {pendingHods.map(h => (
                  <tr key={h._id}>
                    <td>{h.name}</td>
                    <td>{h.email}</td>
                    <td>{h.department}</td>
                    <td style={{ display: 'flex', gap: '0.5rem' }}>
                      <button className="btn btn-green btn-sm" onClick={() => handleApprove(h._id)}>✅ Approve</button>
                      <button className="btn btn-red btn-sm" onClick={() => handleReject(h._id)}>❌ Reject</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* Recent Meetings */}
        <div className="card">
          <h2>Recent Meetings</h2>
          {meetings.length === 0 ? (
            <p style={{ color: '#6b7280', textAlign: 'center', padding: '1rem' }}>No meetings yet.</p>
          ) : (
            <table>
              <thead><tr><th>#</th><th>Staff/HOD</th><th>Scheduled By</th><th>Date</th><th>Time</th><th>Status</th></tr></thead>
              <tbody>
                {meetings.slice(0, 10).map((m, i) => (
                  <tr key={m._id}>
                    <td>{i + 1}</td>
                    <td>{m.attendees?.map(a => a.user?.name).join(', ') || '—'}</td>
                    <td>{m.scheduledBy?.name}</td>
                    <td>{new Date(m.date).toLocaleDateString('en-IN')}</td>
                    <td>{m.time}</td>
                    <td><span className={`badge badge-${m.status}`}>{m.status}</span></td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>

        {/* Blacklist Modal */}
        {blacklistModal && (
          <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 100 }}>
            <div style={{ background: 'white', padding: '2rem', borderRadius: '12px', width: '400px' }}>
              <h2 style={{ color: '#dc2626' }}>Blacklist {blacklistModal.name}</h2>
              <div className="form-group" style={{ marginTop: '1rem' }}>
                <label>Reason</label>
                <textarea value={reason} onChange={e => setReason(e.target.value)} rows="3" placeholder="e.g. Misconduct, Absent repeatedly..." />
              </div>
              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <button className="btn btn-red" onClick={handleBlacklist}>Confirm Blacklist</button>
                <button className="btn btn-gray" onClick={() => { setBlacklistModal(null); setReason(''); }}>Cancel</button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default PrincipalDashboard;
